end

function UIMazeBigMapNode:Refresh(data, clickCb)
    if not data then
        return
    end
    self._data = data
    self._clickCb = clickCb

    self:FillViewMapPoint()
end

function UIMazeBigMapNode:FillViewMapPoint()
    local curPoint = MazeMapMgr:GetInstance().curPoint
    CfUtils.FillImage(self.icon, CfUtils.GetMazeViewMapPoint(self._data.type))

    if self._data.type == Constants.MazePointType.BossBattle then
        CfUtils.SetScale(self.controller.gameObject, Vector3(1.38, 1.38, 1.38))        
    end

    if checkNumber(self._data.line) <= checkNumber(curPoint.line) then
        local isPassPoint = MazeMgr:GetInstance():IsPassCurPoint(self._data)
        if checkNumber(self._data.line) == checkNumber(curPoint.line) then
            if MazeMapMgr:GetInstance():IsCurPoint(self._data) then
                KTool.SetActive(self.isPass,true)
                KTool.SetActive(self.noGetTo,false)

                if isPassPoint then
                    KTool.SetActive(self.pass, checkNumber(self._data.passType) == 1)
                    KTool.SetActive(self.noPass, checkNumber(self._data.passType) == 2)
                    KTool.SetActive(self.noAct, false)
                    if not (checkNumber(self._data.type) == Constants.MazePointType.StartPoint or checkNumber(self._data.type) == Constants.MazePointType.BossBattle) then
                        KTool.SetActive(self.textBg, true)
                        local pointStr = (checkNumber(self._data.line) - 1 < 10 and "0"..(self._data.line - 1) or (self._data.line - 1)).."/"..MazeMapMgr:GetInstance():GetMaxLineNum()
                        CfUtils.FillText(self.Text, pointStr)
                    end
                else
                    KTool.SetActive(self.noAct, true)
                    KTool.SetActive(self.noPass, false)
                    KTool.SetActive(self.pass, false)
                end
            else
                KTool.SetActive(self.isPass,false)
                KTool.SetActive(self.noGetTo,true)
            end
        elseif self._data.line < curPoint.line then
            --该点在历史足迹中
            if isPassPoint then
                KTool.SetActive(self.isPass,true)
                KTool.SetActive(self.noGetTo,false)

                KTool.SetActive(self.pass, checkNumber(self._data.passType) == 1)
                KTool.SetActive(self.noPass, checkNumber(self._data.passType) == 2)
                KTool.SetActive(self.noAct, false)
                if not (checkNumber(self._data.type) == Constants.MazePointType.StartPoint or checkNumber(self._data.type) == Constants.MazePointType.BossBattle) then
                    KTool.SetActive(self.textBg, true)
                    local pointStr = (checkNumber(self._data.line) - 1 < 10 and "0"..(self._data.line - 1) or (self._data.line - 1)).."/"..MazeMapMgr:GetInstance():GetMaxLineNum()
                    CfUtils.FillText(self.Text, pointStr)
                end
            else
                KTool.SetActive(self.isPass,false)
                KTool.SetActive(self.noGetTo,true)
            end
        end        
    else
        KTool.SetActive(self.noGetTo, false)
        KTool.SetActive(self.isPass, false)
    end
    
    --如果是下一关的点
    if MazeMapMgr:GetInstance():IsNextPoints(self._data) then
        --如果通关了当前的点 采取绘制下一关的点
        if MazeMgr:GetInstance():IsPassCurPoint() then
            KTool.SetActive(self.isNextPoint, MazeMapMgr:GetInstance():IsCanArrivePoint(self._data))

            KTool.SetActive(self.isPass, false)
            KTool.SetActive(self.noGetTo, not MazeMapMgr:GetInstance():IsCanArrivePoint(self._data))
        end
    else
        KTool.SetActive(self.isNextPoint, false)
    end
end

function UIMazeBigMapNode:RefreshCurPosNode(isTrue)
    KTool.SetActive(self.isCurPos, isTrue)
end

function UIMazeBigMapNode:OnSelect()
    if self._clickCb then
        self._clickCb()
    end
end

function UIMazeBigMapNode:OnDestroy()
    self.controller = nil--luabehaviour 中CSharp对象
    self:Delete()
    self = nil
end

return UIMazeBigMapNode
